114	            super.addText(node, textOptions, depth);
115	        }
116	
117	        int textTrim(TextNode node, int options) {
118	            if (!isBlockEl(node.parentNode)) return options; // don't trim inline, whitespace significant
119	            Node prev = node.previousSibling();
120	            Node next = node.nextSibling();
121	
122	            // if previous is not an inline element
123	            if (!(prev instanceof Element && !isBlockEl(prev))) {
124	                // if there is no previous sib; or not a text node and should be indented
125	                if (prev == null || !(prev instanceof TextNode) && shouldIndent(prev))
126	                    options |= Entities.TrimLeading;
127	            }
128	
129	            if (next == null || !(next instanceof TextNode) && shouldIndent(next)) {
130	                options |= Entities.TrimTrailing;
131	            } else { // trim trailing whitespace if the next non-empty TextNode has leading whitespace
132	                next = nextNonBlank(next);
133	                if (next instanceof TextNode && StringUtil.isWhitespace(next.nodeValue().codePointAt(0)))
134	                    options |= Entities.TrimTrailing;
135	            }
136	
137	            return options;
138	        }
