140	        boolean shouldIndent(@Nullable Node node) {
141	            if (node == null || node == root || preserveWhitespace || isBlankText(node))
142	                return false;
143	            if (isBlockEl(node))
144	                return true;
145	
146	            Node prevSib = previousNonblank(node);
147	            if (isBlockEl(prevSib)) return true;
148	
149	            Element parent = node.parentNode;
150	            if (!isBlockEl(parent) || parent.tag().is(Tag.InlineContainer) || !hasNonTextNodes(parent))
151	                return false;
152	
153	            return prevSib == null ||
154	                (!(prevSib instanceof TextNode) &&
155	                    (isBlockEl(prevSib) || !(prevSib instanceof Element)));
156	        }
157	
158	        boolean isBlockEl(@Nullable Node node) {
159	            if (node == null) return false;
160	            if (node instanceof Element) {
161	                Element el = (Element) node;
162	                if (el.nameIs("br")) return true; // give <br> a newline; actually an inline tag
163	                return el.isBlock() ||
164	                    (!el.tag.isKnownTag() && (el.parentNode instanceof Document || hasChildBlocks(el)));
165	            }
166	
167	            return false;
168	        }
169	
170	        /**
171	         Returns true if any of the Element's child nodes should indent. Checks the last 5 nodes only (to minimize
172	         scans).
173	         */
174	        static boolean hasChildBlocks(Element el) {
175	            Element child = el.firstElementChild();
176	            for (int i = 0; i < maxScan && child != null; i++) {
177	                if (child.isBlock() || !child.tag.isKnownTag()) return true;
178	                child = child.nextElementSibling();
179	            }
180	            return false;
181	        }
182	        static private final int maxScan = 5;
183	
184	        static boolean hasNonTextNodes(Element el) {
185	            Node child = el.firstChild();
186	            for (int i = 0; i < maxScan && child != null; i++) {
187	                if (!(child instanceof TextNode)) return true;
188	                child = child.nextSibling();
189	            }
190	            return false;
191	        }
192	
193	        static @Nullable Node previousNonblank(Node node) {
194	            Node prev = node.previousSibling();
195	            while (isBlankText(prev)) prev = prev.previousSibling();
196	            return prev;
197	        }
198	
199	        static @Nullable Node nextNonBlank(@Nullable Node node) {
200	            while (isBlankText(node)) node = node.nextSibling();
201	            return node;
202	        }
203	
204	        static boolean isBlankText(@Nullable Node node) {
205	            return node instanceof TextNode && ((TextNode) node).isBlank();
206	        }
207	
208	        static boolean tagIs(int option, @Nullable Node node) {
209	            return node instanceof Element && ((Element) node).tag.is(option);
210	        }
211	    }
212	
213	    /** Outline Printer */
214	    static class Outline extends Pretty {
215	        Outline(Node root, QuietAppendable accum, OutputSettings settings) {
216	            super(root, accum, settings);
217	        }
218	
219	        @Override
220	        boolean isBlockEl(@Nullable Node node) {
221	            return node != null;
222	        }
223	
224	        @Override
225	        boolean shouldIndent(@Nullable Node node) {
226	            if (node == null || node == root || preserveWhitespace || isBlankText(node))
227	                return false;
228	            if (node instanceof TextNode) {
229	                return node.previousSibling() != null || node.nextSibling() != null;
230	            }
231	            return true;
232	        }
233	    }
234	
235	    static Printer printerFor(Node root, QuietAppendable accum) {
236	        OutputSettings settings = NodeUtils.outputSettings(root);
237	        if (settings.outline())     return new Printer.Outline(root, accum, settings);
238	        if (settings.prettyPrint()) return new Printer.Pretty(root, accum, settings);
239	        return new Printer(root, accum, settings);
240	    }
241	}
