/**
 Checks if the node is contained (at any depth up to the serialization root) in an inline element such as
 {@code code}, {@code b}, or {@code span}. Cosmetic line breaks are never emitted there: whitespace inside an
 inline element is rendered by browsers, so an indentation newline would survive a re-parse as visible text
 and make e.g. cleaning the cleaned output add spaces that were not in the source.
 */
boolean inInlineContext(@Nullable Node node) {
    Node parent = node == null ? null : node.parentNode;
    while (parent != null) {
        if (parent instanceof Element && !isBlockEl(parent)) return true;
        if (parent == root) break;
        parent = parent.parentNode;
    }
    return false;
}

