/**
 Checks if the node is contained (at any depth up to the serialization root) in a purely inline element such as
 {@code code}, {@code b}, or {@code span} that holds no structural block content. Cosmetic line breaks are
 never emitted there: whitespace inside such an element is rendered by browsers, so an indentation newline
 would survive a re-parse as visible text and make e.g. cleaning the cleaned output add spaces that were not
 in the source. An inline element that does carry block flow (such as {@code <a><div>}) or foreign content is
 formatted structurally, as the newlines sit adjacent to block-level nodes and remain blank text.
 */
boolean inInlineContext(@Nullable Node node) {
    Node parent = node == null ? null : node.parentNode;
    while (parent != null) {
        if (parent instanceof Element && !isBlockEl(parent) && !hasStructuralBlock((Element) parent))
            return true;
        if (parent == root) break;
        parent = parent.parentNode;
    }
    return false;
}

/** Whether an element contains an immediate child that is structural block content (not a {@code <br>} or other
 inline node), including foreign (SVG / MathML) content. */
private static boolean hasStructuralBlock(Element el) {
    for (Element child : el.children()) {
        if (child.nameIs("br")) continue;
        if (!child.tag.namespace().equals(Tag.NamespaceHtml) || child.tag.is(Tag.Block)) return true;
    }
    return false;
}

