import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
public class Ns {
    static void tree(String in){
        Document d = Jsoup.parseBodyFragment(in);
        StringBuilder sb=new StringBuilder();
        walk(d.body(), sb, 0);
        System.out.println(in+"\n  "+sb+"\n");
    }
    static void walk(Node n, StringBuilder sb, int d){
        if (n instanceof Element) {
            sb.append("<").append(((Element)n).tagName()).append("> ");
            for(Node c: n.childNodes()) walk(c,sb,d+1);
        } else if (n instanceof TextNode) sb.append("T[").append(((TextNode)n).getWholeText().replace("\n","\\n")).append("] ");
    }
