/** Upper bound on re-parse passes while converging the clean output to its own fixed point. */
private static final int MaxNormalizePasses = 8;

/**
 Reparses the clean body and runs the copy again until the serialized output equals its own re-parse. The initial
 copy mirrors the (possibly malformed) source tree, so parser recovery that only happens on a fresh parse -- such as
 a nested {@code <p>} being split, a stray table cell being dropped, or table content being fostered -- could leave
 a structure that parses differently when the cleaned output is parsed again. Driving the output through the parser
 once makes the returned document identical to what a second clean produces, without changing anything when the
 initial copy is already stable.
 */
private Document normalizeToFixedPoint(Document clean) {
    String baseUri = clean.baseUri();
    String html = clean.body().html();
    Document result = clean;
    for (int pass = 0; pass < MaxNormalizePasses; pass++) {
        Document reparsed = Document.createShell(baseUri);
        List<Node> nodes = Parser.parseFragment(html, reparsed.body(), baseUri);
        reparsed.body().insertChildren(0, nodes);

        Document next = Document.createShell(baseUri);
        copySafeNodes(reparsed.body(), next.body());
        next.outputSettings(clean.outputSettings().clone());

        String nextHtml = next.body().html();
        result = next;
        if (nextHtml.equals(html)) break;
        html = nextHtml;
    }
    return result;
}

