import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.safety.*;
import java.util.*;

public class Fuzz2 {
    static Random rnd;
    static final String[] A = {"p","pre","code","textarea","b","i","br","table","tr","td","div","span","a","img"};
    static final String[] D = {"script","style","iframe","object","embed","applet","link","meta","base","form","input","button","select","option","noscript","template","plaintext","title","head","body","html","p","td","tr"};
    static final String[] TX = {"", " ", "  ", "\n", "\t", "a", "x y", " & ", "<", "&amp;", "&amp;amp;", "&lt;", "&#65;", "&nbsp;"};

    public static void main(String[] args){
        long seed = Long.parseLong(args[0]);
        int iters = Integer.parseInt(args[1]);
        rnd = new Random(seed);
        Safelist[] lists = {
            Safelist.none().addTags("p","pre","code","textarea","b","i","br","table","tr","td","div","span"),
            Safelist.relaxed(),
            Safelist.basic(),
            Safelist.none(),
            Safelist.none().addTags("p","a","img").addAttributes("a","href").addAttributes("img","src").addProtocols("a","href","http","https","#").addProtocols("img","src","http","https"),
        };
        for (int it=0; it<iters; it++) {
            String html = gen(0);
            int idx = rnd.nextInt(lists.length);
            Safelist sl = lists[idx];
            String o1, o2;
            try {
                o1 = Jsoup.clean(html, sl);
                o2 = Jsoup.clean(o1, sl);
            } catch (Exception e) { System.out.println("EXC sl="+idx+" html="+html.replace("\n","\\n")); continue; }
            if (!o1.equals(o2)) {
                System.out.println("FAIL sl="+idx+"\n  in ="+html.replace("\n","\\n").replace("\t","\\t")
                    +"\n  o1 ="+o1.replace("\n","\\n").replace("\t","\\t")
                    +"\n  o2 ="+o2.replace("\n","\\n").replace("\t","\\t"));
            }
        }
    }

    static String gen(int depth){
        StringBuilder sb=new StringBuilder();
        int kids=rnd.nextInt(4);
        for(int k=0;k<kids;k++){
            int pick=rnd.nextInt(10);
            if(pick<4) sb.append(TX[rnd.nextInt(TX.length)]);
            else if(pick<9 && depth<3){
                boolean danger = rnd.nextInt(10)<5;
                String tag = danger? D[rnd.nextInt(D.length)] : A[rnd.nextInt(A.length)];
                sb.append("<").append(tag);
                if (rnd.nextBoolean()) {
                    String[] at={" onclick=1"," href=x"," class=c"," ",""};
                    sb.append(at[rnd.nextInt(at.length)]);
                }
                sb.append(">");
                boolean raw = tag.equals("script")||tag.equals("style")||tag.equals("textarea")||tag.equals("plaintext")||tag.equals("title");
                if(raw){ sb.append(TX[rnd.nextInt(TX.length)]); if(!tag.equals("plaintext")) sb.append("</").append(tag).append(">"); }
                else { sb.append(gen(depth+1)).append("</").append(tag).append(">"); }
            } else sb.append("</").append(A[rnd.nextInt(A.length)]).append(">");
        }
        return sb.toString();
    }
}
