import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.safety.*;
import org.jsoup.select.Elements;

public class Spec {
    static int pass=0, fail=0;
    static void check(String name, boolean cond, String detail){
        if (cond) pass++; else { fail++; System.out.println("FAIL: "+name+"  "+detail); }
    }
    static Safelist SL = Safelist.none().addTags("p","pre","code","textarea","b","i","br","table","tr","td","div","span")
        .addAttributes(":all","class").addAttributes("a","href");
    static Safelist A = Safelist.none().addTags("a","p").addAttributes("a","href");

    static String idem(String html, Safelist sl){
        String o1=Jsoup.clean(html,sl), o2=Jsoup.clean(o1,sl), o3=Jsoup.clean(o2,sl);
        check("idempotent ["+html.substring(0,Math.min(30,html.length()))+"]", o1.equals(o2)&&o2.equals(o3),
            "\n  o1="+o1.replace("\n","\\n")+"\n  o2="+o2.replace("\n","\\n"));
        return o1;
    }

    public static void main(String[] x){
        // 1. pre/code/textarea whitespace + literal brackets + entities visible
        String pre = "<pre>  a\tb\nc &lt; d &amp;amp; </pre>";
        check("pre ws", idem(pre, SL).equals(pre), idem(pre,SL));
        String ta = "<textarea>  x\ny &lt; z &amp; w</textarea>";
        check("textarea ws", idem(ta, SL).equals(ta), idem(ta,SL));
        // code whitespace: browser-normalized but idempotent & entities once
        String code = "<code>a &amp;amp; b &lt; c  d</code>";
        String co = idem(code, SL);
        check("code entities once", co.contains("&amp;amp;") && co.contains("&lt;"), co);

        // 2. entities decoded once in normal text
        check("entity once", idem("<p>&amp;amp; &amp;lt; &lt;b&gt;</p>", SL).equals("<p>&amp;amp; &amp;lt; &lt;b&gt;</p>"), "");

        // 3. dangerous content never re-executable; wrapped text preserved
        String danger = idem("<p>Hello<script>alert(1)</script>world</p>", SL);
        check("script removed, text kept", danger.equals("<p>Helloworld</p>"), danger);
        String ev = idem("<p onclick='alert(1)'>x</p>", SL);
        check("event attr removed", ev.equals("<p>x</p>"), ev);

        // 4. rejected wrapper promotes safe subtree in order
        String prom = idem("<center><p>One</p><p>Two</p></center>", SL);
        check("promote order", prom.equals("<p>One</p>\n<p>Two</p>"), prom);
        String nested = idem("<div><span><b>1</b><i>2</i></span></div>", SL);
        check("nested promote", nested.equals("<b>1</b><i>2</i>"), nested);

        // 5. blocks don't stick together
        String blocks = idem("<div><p>One</p><p>Two</p></div>", SL);
        check("blocks separate", blocks.contains("</p>\n<p>"), blocks);

        // 6. malformed table
        idem("<table><p>x</p><tr><td>y</td></tr></table>", SL);

        // 7. empty / all-rejected / malformed -> no throw
        try { check("empty", Jsoup.clean("", SL).isEmpty(), ""); } catch(Exception e){check("empty",false,e+"");}
        try { String r=Jsoup.clean("<script>x</script><style>y</style>", SL); check("all rejected", r.isEmpty(), r);} catch(Exception e){check("all rejected",false,e+"");}
        try { Jsoup.clean("<<<>>>>\0broken", SL); check("malformed no throw", true, "");} catch(Exception e){check("malformed no throw",false,e+"");}

        // 8. original document not modified
        Document orig = Jsoup.parseBodyFragment("<p onclick=1>Hi<script>x</script></p>");
        String origHtml = orig.body().html();
        Jsoup.clean(orig.body().html(), SL);
        check("original doc untouched", orig.body().html().equals(origHtml), orig.body().html());

        // 9. call independence
        Safelist shared = Safelist.none().addTags("p","b");
        String r1 = Jsoup.clean("<p>x</p>", shared);
        String r2 = Jsoup.clean("<script>y</script>", shared);
        check("independence", r1.equals("<p>x</p>") && !r2.isEmpty()==false, r1+"/"+r2);

        // 10. reparse -> same selectors, hierarchy, attrs, visible text
        String frag = "<p class=keep>a<b>bold</b></p><div><span><i>i</i></span></div><pre>  x\n y</pre>";
        String out = Jsoup.clean(frag, SL);
        Document d1=Jsoup.parseBodyFragment(out), d2=Jsoup.parseBodyFragment(Jsoup.clean(out,SL));
        Elements e1=d1.select("p,b,i,pre,div,span"), e2=d2.select("p,b,i,pre,div,span");
        boolean same=e1.size()==e2.size();
        for(int i=0;same&&i<e1.size();i++){
            same = e1.get(i).normalName().equals(e2.get(i).normalName())
                && e1.get(i).text().equals(e2.get(i).text())
                && e1.get(i).attr("class").equals(e2.get(i).attr("class"));
        }
        check("reparse selectors", same, e1+" vs "+e2);
        check("class retained", d1.selectFirst("p").attr("class").equals("keep"), "");

        // 11. url attr safety
        check("js url dropped", Jsoup.clean("<a href=\"javascript:alert(1)\">x</a>", A).equals("<a>x</a>"), "");
        check("http url kept", Jsoup.clean("<a href=\"http://e.com/\">x</a>", A).contains("http://e.com/"), "");

        // 12. invisible char must not appear
        check("no phantom char", !out.contains("\u0000"), "");

        // 13. textarea literal tags visible
        String tt = idem("<textarea>&lt;script&gt;x&lt;/script&gt;</textarea>", SL);
        check("textarea literal", tt.equals("<textarea>&lt;script&gt;x&lt;/script&gt;</textarea>"), tt);

        System.out.println("\nPASS="+pass+" FAIL="+fail);
        if (fail>0) System.exit(1);
    }
}
