10	/** Base Printer */
11	class Printer implements NodeVisitor {
12	    final Node root;
13	    final QuietAppendable accum;
14	    final OutputSettings settings;
15	
16	    Printer(Node root, QuietAppendable accum, OutputSettings settings) {
17	        this.root = root;
18	        this.accum = accum;
19	        this.settings = settings;
20	    }
21	
22	    void addHead(Element el, int depth) {
23	        el.outerHtmlHead(accum, settings);
24	    }
25	
26	    void addTail(Element el, int depth) {
27	        el.outerHtmlTail(accum, settings);
28	    }
29	
30	    void addText(TextNode textNode, int textOptions, int depth) {
31	        int options = Entities.ForText | textOptions;
32	        Entities.escape(accum, textNode.coreValue(), settings, options);
33	    }
34	
35	    void addNode(LeafNode node, int depth) {
36	        node.outerHtmlHead(accum, settings);
37	    }
38	
39	    void indent(int depth) {
40	        accum.append('\n').append(StringUtil.padding(depth * settings.indentAmount(), settings.maxPaddingWidth()));
41	    }
42	
43	    @Override
44	    public void head(Node node, int depth) {
45	        if (node.getClass() == TextNode.class)  addText((TextNode) node, 0, depth); // Excludes CData; falls to addNode
46	        else if (node instanceof Element)       addHead((Element) node, depth);
47	        else                                    addNode((LeafNode) node, depth);
48	    }
49	
50	    @Override
51	    public void tail(Node node, int depth) {
52	        if (node instanceof Element) { // otherwise a LeafNode
53	            addTail((Element) node, depth);
54	        }
55	    }
56	
57	    /** Pretty Printer */
58	    static class Pretty extends Printer {
59	        boolean preserveWhitespace = false;
60	
61	        Pretty(Node root, QuietAppendable accum, OutputSettings settings) {
62	            super(root, accum, settings);
63	
64	            // check if there is a pre on stack
65	            for (Node node = root; node != null; node = node.parentNode()) {
66	                if (tagIs(Tag.PreserveWhitespace, node)) {
67	                    preserveWhitespace = true;
68	                    break;
69	                }
70	            }
71	        }
72	
73	        @Override
74	        void addHead(Element el, int depth) {
75	            if (shouldIndent(el))
76	                indent(depth);
77	            super.addHead(el, depth);
78	            if (tagIs(Tag.PreserveWhitespace, el)) preserveWhitespace = true;
79	        }
80	
81	        @Override
82	        void addTail(Element el, int depth) {
83	            if (shouldIndent(nextNonBlank(el.firstChild()))) {
84	                indent(depth);
85	            }
86	            super.addTail(el, depth);
87	
88	            // clear the preserveWhitespace if this element is not, and there are none on the stack above
89	            if (preserveWhitespace && el.tag.is(Tag.PreserveWhitespace)) {
90	                for (Element parent = el.parent(); parent != null; parent = parent.parent()) {
91	                    if (parent.tag().preserveWhitespace()) return; // keep
92	                }
93	                preserveWhitespace = false;
94	            }
95	        }
96	
97	        @Override
98	        void addNode(LeafNode node, int depth) {
99	            if (shouldIndent(node))
100	                indent(depth);
101	            super.addNode(node, depth);
102	        }
103	
104	        @Override
105	        void addText(TextNode node, int textOptions, int depth) {
106	            if (!preserveWhitespace) {
107	                textOptions |= Entities.Normalise;
108	                textOptions = textTrim(node, textOptions);
109	
110	                if (!node.isBlank() && isBlockEl(node.parentNode) && shouldIndent(node))
111	                    indent(depth);
112	            }
113	
114	            super.addText(node, textOptions, depth);
115	        }
